$("#code_ewm_bottom").text("");//初始化二维码的位置

    jQuery("#code_ewm_bottom").qrcode({
        render: 'canvas',
        height: 135,
        width: 135,
        text: 'http://www.bjxch.gov.cn/xcdt/xxxq/pnidpv966867.html'     // 二维码地址
    });
    //下载
    function downloadQR() {
        console.log("下载二维码");
        try {
            // 获取二维码容器内的canvas元素
            const canvas = document.querySelector('#code_ewm_bottom canvas');
            if (!canvas) {
                layui.use('layer', function () {
                    layer.msg('未找到二维码，请稍后重试！');
                })
                return;
            }
            // 将canvas转换为图片URL
            canvas.toBlob(function(blob) {
                if (!blob) {
                    layui.use('layer', function () {
                        layer.msg('二维码转换失败！');
                    })
                    return;
                }
                // 创建下载链接
                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                // 设置下载属性
                a.href = url;
                a.download = '二维码图片.png'; // 下载文件名
                // 模拟点击下载
                document.body.appendChild(a);
                a.click();
                // 清理资源
                document.body.removeChild(a);
                URL.revokeObjectURL(url);
                // 显示下载成功提示
                layui.use('layer', function () {
                    layer.msg('二维码已下载！');
                })
            });
        } catch (error) {
            console.error('下载二维码出错:', error);
            layui.use('layer', function () {
                layer.msg('下载失败，请重试！');
            })
        }
    }
    // 长按识别功能支持 - 需要配合CSS使用
    // 页面加载完成后添加辅助属性
    $(document).ready(function() {
        // 为二维码容器添加触摸相关属性，帮助浏览器识别
        const qrContainer = document.getElementById('code_ewm_bottom');
        qrContainer.setAttribute('title', '长按可识别二维码');
        qrContainer.setAttribute('aria-label', '二维码：长按可识别，点击可下载');

        // 创建隐藏的img元素用于长按识别（部分浏览器需要）
        const canvas = document.querySelector('#code_ewm_bottom canvas');
        if (canvas) {
            const img = document.createElement('img');
            img.src = canvas.toDataURL('image/png');
            img.style.display = 'block';
            img.className = 'qr-hidden-image';
            img.alt = '二维码图片';
            qrContainer.appendChild(img);
            //再隐藏canvas
			canvas.style.display = 'none';
        }
    });
